-- Reference only; do not execute directly on a school database.


-- GetSchoolOfficials
CREATE   PROCEDURE dbo.GetSchoolOfficials
@UserId INT
AS
BEGIN
    SET NOCOUNT ON;
    EXECUTE dbo.RequireAuthenticatedUser @UserId;
    SELECT   SchoolOfficialId,
             Designation,
             PersonName,
             CreatedAt,
             CreatedByUserId,
             UpdatedAt,
             UpdatedByUserId
    FROM     dbo.SchoolOfficials
    ORDER BY Designation, PersonName;
END
